        "quote": "请调取 CareLoop 联合医疗网络内已授权、已同步的骨科手术/住院安排"
      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00042",
        "explanation": "识别了抗凝和头孢不能自行使用，但未同步要求核对头孢/青霉素过敏史。",
        "quote": "头孢唑林也通常由医院在术前静滴"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00042",
        "explanation": "把家属找不全药的现实问题转化为联系护士站和带原包装核对。",
        "quote": "把所有药盒、药袋、处方和保健品原包装带去"
      }
    ]
  },
